import sys
import re


def main():
    text = sys.stdin.read()

    variables = {}
    order = list("abcdefghijklmnop") + ["TMP"]

    # Matches "name <- value", where value is a variable name or an integer.
    pattern = re.compile(r'([A-Za-z_][A-Za-z_0-9]*)\s*<-\s*(-?\d+|[A-Za-z_][A-Za-z_0-9]*)')

    for statement in text.split(';'):
        match = pattern.search(statement)
        if not match:
            continue

        target, source = match.group(1), match.group(2)

        if re.fullmatch(r'-?\d+', source):
            variables[target] = int(source)
        else:
            variables[target] = variables.get(source, 0)

    parts = [f"{name} ?= {variables.get(name, 0)};" for name in order]
    print(" ".join(parts))


if __name__ == "__main__":
    main()
